import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph SMB Latest Updates and Future Roadmap","description":"","frontmatter":{"title":"Ceph SMB Latest Updates and Future Roadmap","date":"2026-07-09T00:00:00.000Z","updated":"2026-07-10T00:00:00.000Z","tags":["Ceph","CephFS","RGW","文件系统存储","会议纪要"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_SMB_Latest_Updates_and_Future_Roadmap.md","filePath":"posts/2026/Ceph_SMB_Latest_Updates_and_Future_Roadmap.md","lastUpdated":null}'),i={name:"posts/2026/Ceph_SMB_Latest_Updates_and_Future_Roadmap.md"};function s(n,e,l,p,c,d){return r(),t("div",null,[...e[0]||(e[0]=[o('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本文整理自 Sachin Prabhu（IBM SEF SMB 团队）在 Ceph 社区会议上的演讲，介绍了过去一年 Ceph SMB 模块的新特性，以及当前正在积极开发、预计近期合入主线的功能。</p><h2 id="团队介绍" tabindex="-1">团队介绍 <a class="header-anchor" href="#团队介绍" aria-label="Permalink to &quot;团队介绍&quot;">​</a></h2><p>演讲者所在团队是 IBM 内部的 SEF SMB 小组，核心成员来自 Red Hat 收购后并入 IBM 的工程师，其中不乏 Samba 上游开发者。团队在 GitHub 上的账号命名为 <code>sambar</code> 和 <code>Kubernetes</code>，原因是这些组件最初是为 Kubernetes 的 Samba CSI driver 开发的，后来也用于 Ceph SMB 场景。</p><p>主要开源组件包括：</p><ul><li><strong>samba-container</strong>：Samba 主容器及 winbind、CTDB 等 sidecar 容器</li><li><strong>samba-build</strong>：将上下游 Samba 源码编译为 RPM 包的工具</li><li><strong>samba-cc</strong>：容器内服务启动的辅助工具</li><li>测试框架：集成 fio、small files、samba torture 等标准测试工具，支持从零构建一致的测试环境</li></ul><h2 id="ceph-smb-manager-模块简介" tabindex="-1">Ceph SMB Manager 模块简介 <a class="header-anchor" href="#ceph-smb-manager-模块简介" aria-label="Permalink to &quot;Ceph SMB Manager 模块简介&quot;">​</a></h2><p>Ceph SMB Manager 模块的核心功能：</p><ul><li>提供 <code>ceph smb</code> 子命令，用于管理 SMB 服务</li><li>负责服务编排，包括读取 spec、启动 init container（配置校验）、SMBD 容器（文件服务）、CTDB sidecar（集群化多节点通信）、winbind（SID 到账号名映射）、Prometheus 指标采集</li></ul><p><strong>服务创建方式</strong>：</p><ol><li><strong>命令式（Imperative）</strong>：直接在命令行传入参数，例如创建使用 Active Directory 认证的集群，并设置自定义 DNS 和 share。</li><li><strong>声明式（Declarative，推荐）</strong>：编写 YAML/JSON 服务定义文件，通过 <code>ceph smb apply</code> 应用，更易于版本管理和自动化。</li></ol><p>支持特性：用户/组访问控制、Active Directory 集成、多节点 clustering、服务 placement 定义，以及 Go binding。</p><h2 id="已合入主线的新特性" tabindex="-1">已合入主线的新特性 <a class="header-anchor" href="#已合入主线的新特性" aria-label="Permalink to &quot;已合入主线的新特性&quot;">​</a></h2><h3 id="_1-io-速率限制-io-rate-limiting" tabindex="-1">1. IO 速率限制（IO Rate Limiting） <a class="header-anchor" href="#_1-io-速率限制-io-rate-limiting" aria-label="Permalink to &quot;1. IO 速率限制（IO Rate Limiting）&quot;">​</a></h3><p><strong>背景</strong>：解决&quot;嘈杂邻居&quot;（noisy neighbor）问题，防止某个高负载 share 独占集群资源。</p><p><strong>实现</strong>：与上游 Samba 社区协商后，选择通用方案而非直接修改 Ceph 模块，开发了新 Samba VFS 模块 <strong>VFS AIO Rate Limit</strong>。</p><p><strong>功能点</strong>：</p><ul><li>以 share 为粒度设置速率限制，且限制在集群范围内生效</li><li>支持读/写 IOPS 分别限制</li><li>支持读/写带宽分别限制</li><li>支持 burst（突发流量）：超出限额的部分会被计入后续周期，长期来看符合设定值</li></ul><p>相关分享可参考 Awan 在 SambaXP 的演讲。</p><h3 id="_2-smb-per-share-指标-per-share-metrics" tabindex="-1">2. SMB Per-Share 指标（Per-Share Metrics） <a class="header-anchor" href="#_2-smb-per-share-指标-per-share-metrics" aria-label="Permalink to &quot;2. SMB Per-Share 指标（Per-Share Metrics）&quot;">​</a></h3><p><strong>背景</strong>：原有 SMB 指标通过 <code>samba-status</code> 命令输出并以 Prometheus endpoint 形式暴露，但粒度为整体服务级别。用户需要 per-share 粒度的监控数据。</p><p><strong>实现</strong>：Shahar 与上游 Samba 社区合作，新增 per-share 级别的 profiling counter。</p><p><strong>可监控项</strong>：</p><ul><li>吞吐量（throughput）</li><li>IOPS</li><li>延迟（latency，指 Samba 服务端到后端文件系统之间的延迟）</li></ul><h3 id="_3-多通道支持-multi-channel-support" tabindex="-1">3. 多通道支持（Multi-Channel Support） <a class="header-anchor" href="#_3-多通道支持-multi-channel-support" aria-label="Permalink to &quot;3. 多通道支持（Multi-Channel Support）&quot;">​</a></h3><p>基于 Samba 上游已有特性，在服务端与客户端之间存在多条网络连接时，可聚合网络带宽，同时提升容错能力（任一链路故障时 IO 不中断）。支持具备 RSS 特性的网卡。此特性基本不需要 Ceph 侧额外开发，主要新增了 QE 测试用例以验证行为符合预期。</p><h3 id="_4-基于-ip-的访问控制-ip-based-access-control" tabindex="-1">4. 基于 IP 的访问控制（IP-Based Access Control） <a class="header-anchor" href="#_4-基于-ip-的访问控制-ip-based-access-control" aria-label="Permalink to &quot;4. 基于 IP 的访问控制（IP-Based Access Control）&quot;">​</a></h3><p>允许将 SMB share 的访问限制在特定 IP 地址、IP 列表或子网范围内。配置的 IP 信息会转换为等价的 <code>smb.conf</code> 配置项并应用到服务。</p><h3 id="_5-自带密钥加密-bring-your-own-key-byok" tabindex="-1">5. 自带密钥加密（Bring Your Own Key，BYOK） <a class="header-anchor" href="#_5-自带密钥加密-bring-your-own-key-byok" aria-label="Permalink to &quot;5. 自带密钥加密（Bring Your Own Key，BYOK）&quot;">​</a></h3><p><strong>场景</strong>：多租户场景下，各租户需要独立保护自身数据，防止其他租户访问。</p><p><strong>特点</strong>：密钥生命周期完全由集群所有者控制。</p><p><strong>配置项</strong>：</p><ul><li><code>keybridge</code>：指定 KMS（Key Management Server）</li><li>每个 share 独立指定使用的加密密钥</li></ul><h3 id="_6-grpc-远程控制-remote-control-via-grpc" tabindex="-1">6. gRPC 远程控制（Remote Control via gRPC） <a class="header-anchor" href="#_6-grpc-远程控制-remote-control-via-grpc" aria-label="Permalink to &quot;6. gRPC 远程控制（Remote Control via gRPC）&quot;">​</a></h3><p><strong>背景</strong>：<code>ceph smb</code> 命令是异步执行的，无法实时获知操作完成状态，不适合用于需要立即反馈的调试场景（如开启 debug 日志级别）。</p><p><strong>实现</strong>：新增一个 sidecar container 运行 gRPC server，通过 gRPC client 与之通信。</p><p><strong>支持命令</strong>：</p><ul><li>获取配置 dump（<code>config dump</code>）</li><li>查询 share 列表</li><li>查看容器内 daemon 状态</li><li><code>ctdb status</code> 和 <code>ctdb moveip</code></li><li>设置 debug 级别（<code>set debug level</code>）</li></ul><p><strong>注意</strong>：不建议用户直接使用 gRPC client，团队已开发并近期合入了一个封装工具，通过 Unix socket 从宿主机连接到 SMB 服务器，调用上述命令。</p><h2 id="正在开发中的新特性" tabindex="-1">正在开发中的新特性 <a class="header-anchor" href="#正在开发中的新特性" aria-label="Permalink to &quot;正在开发中的新特性&quot;">​</a></h2><h3 id="_7-smb-over-rgw-对象存储-smb-导出" tabindex="-1">7. SMB over RGW（对象存储 SMB 导出） <a class="header-anchor" href="#_7-smb-over-rgw-对象存储-smb-导出" aria-label="Permalink to &quot;7. SMB over RGW（对象存储 SMB 导出）&quot;">​</a></h3><p><strong>目标</strong>：通过 SMB 协议导出 Ceph 对象存储（Object Storage），为 Windows/Mac 客户端提供透明的对象存储访问。</p><p><strong>实现</strong>：开发了新 Samba VFS 模块 <strong>VFS RGW</strong>，基于 <code>libRGW</code> 库。</p><p><strong>当前限制</strong>（继承自 libRGW）：</p><ul><li>支持目录列举、文件读取、文件写入（仅 sync 模式）</li><li>不支持目录重命名（受限于对象名/label 的命名方式）</li><li>不支持高级 ACL</li><li>不支持随机写（random write）</li></ul><p><strong>进展</strong>：已有 Samba merge request，预计数周内合入上游 Samba。Venit 在今年 SambaXP 上有专题演讲可供参考。</p><h3 id="_8-macos-客户端支持-mac-os-support" tabindex="-1">8. macOS 客户端支持（Mac OS Support） <a class="header-anchor" href="#_8-macos-客户端支持-mac-os-support" aria-label="Permalink to &quot;8. macOS 客户端支持（Mac OS Support）&quot;">​</a></h3><p><strong>问题</strong>：macOS 客户端使用了 Windows 不支持的特殊字符及 Apple 扩展特性，直接连接会出现兼容性问题，表现为大量 <code>.</code> 前缀的元数据文件。</p><p><strong>实现</strong>：启用 Samba 的 <strong>VFS Fruit</strong> 模块：</p><ul><li>在协商阶段声明支持 Apple SMB 扩展，macOS 客户端自动识别并使用兼容模式</li><li>改善目录查找性能</li><li>支持 macOS streams（用于存储图标等元数据）</li><li>启用 Apple 特有特性，如服务端复制（server-side copy，数据不经过客户端直接在服务端完成）</li></ul><p>元数据存储方式为 XATTR 或目录结构（具体机制待确认）。</p><h2 id="问答摘要" tabindex="-1">问答摘要 <a class="header-anchor" href="#问答摘要" aria-label="Permalink to &quot;问答摘要&quot;">​</a></h2><ul><li><strong>Q：如何查看连接的客户端？</strong><br> A：可通过 <code>samba-status</code> 命令输出的 metrics 中获取，包括已连接客户端数量及列表。通过 gRPC 远程控制工具也可以强制断开（kill）指定客户端连接。</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>Ceph SMB 模块在过去一年持续演进，从 IO 速率限制、per-share 监控、多通道支持到 BYOK 加密和 gRPC 远程控制，功能已相当完善。近期最值得关注的两个方向是 <strong>SMB over RGW</strong>（打通对象存储访问路径）和 <strong>macOS 客户端兼容性</strong>，均预计在 Squid/Reef 后续版本中正式落地。</p>',55)])])}const g=a(i,[["render",s]]);export{u as __pageData,g as default};
